   const built=buildDistrictBatch(basic);if(built.faces.length){const mesh=new Mesh({spatialReference:{wkid:4326},vertexSpace:{type:'georeferenced'},vertexAttributes:{position:new Float64Array(built.position),color:new Uint8Array(built.color)},components:[{faces:new Uint32Array(built.faces),material:{color:'white',doubleSided:true},shading:'flat'}]});layer.add(new Graphic({geometry:mesh,symbol:{type:'mesh-3d',symbolLayers:[{type:'fill'}]}}));}
